test('school design studio previews saves drafts and publishes a selected design',async({page})=>{
 test.setTimeout(150000);await page.setViewportSize({width:1440,height:1100});await signIn(page,'principal@netaji.school');const fixture=await page.evaluate(async()=>({config:await(await fetch('/api/operations/configuration')).json(),me:await(await fetch('/api/auth/me')).json()}));const config=structuredClone(fixture.config);let publishes=0;
 await page.route('**/api/operations/configuration',route=>route.fulfill({json:config}));await page.route('**/api/auth/me',route=>route.fulfill({json:{...fixture.me,theme:{...fixture.me.theme,...config.branding}}}));await page.route('**/api/operations/configuration/design',async route=>{const body=route.request().postDataJSON();expect(body.version).toBe(config.branding.version);expect(body.draftVersion).toBe(config.designDraft?.version??0);const design=normalizeDesign(body.design);if(body.action==='publish'){publishes++;config.branding={...config.branding,version:config.branding.version+1,accent:design.primary,config:{...config.branding.config,design}};}config.designDraft={version:(config.designDraft?.version??0)+1,payload:{design,status:body.action==='draft'?'draft':'published',brandVersion:config.branding.version}};await route.fulfill({json:{ok:true,design,version:config.branding.version,draftVersion:config.designDraft.version}});});
 await page.locator('.sidebar').getByRole('button',{name:'Brand studio',exact:true}).click();await expect(page.locator('.design-preset')).toHaveCount(4);await page.locator('.design-preset').filter({hasText:'Soft & Colourful'}).click();await page.getByLabel('Card shape',{exact:true}).selectOption('crisp');await page.getByLabel('Navigation',{exact:true}).selectOption('standard');await page.getByLabel('Spacing',{exact:true}).selectOption('compact');await page.getByLabel('Primary colour',{exact:true}).fill('#ffff00');await expect(page.locator('.design-note').filter({hasText:'adjusted in the preview'})).toBeVisible();await expect(page.getByRole('button',{name:'Publish school design',exact:true})).toBeDisabled();await page.getByRole('button',{name:'Save draft',exact:true}).click();await expect(page.getByRole('status')).toContainText('Draft saved');expect(publishes).toBe(0);expect(config.branding.config.design).toBeUndefined();
 await page.getByLabel('Preview role',{exact:true}).selectOption('teacher');await page.getByRole('button',{name:'My School Day',exact:true}).click();await expect(page.locator('.dp-content')).toContainText('Your Timeline');await page.getByRole('button',{name:'Desktop',exact:true}).click();await expect(page.locator('.design-preview-stage')).toHaveAttribute('data-device','desktop');await page.getByRole('button',{name:'Mobile',exact:true}).click();await page.getByLabel('Preview role',{exact:true}).selectOption('parent');await page.getByRole('button',{name:'School Feed',exact:true}).click();await page.getByLabel('I reviewed the colours, readability and preview for this design.',{exact:true}).check();await page.getByRole('button',{name:'Publish school design',exact:true}).click();await expect(page.getByRole('status')).toContainText('Design published');expect(publishes).toBe(1);await expect(page.locator('html')).toHaveAttribute('data-school-design','lavender');await expect(page.locator('html')).toHaveAttribute('data-school-navigation','standard');
 await page.screenshot({path:'docs/screenshots/school-design-studio-desktop.png',fullPage:true});await page.setViewportSize({width:390,height:844});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:'docs/screenshots/school-design-studio-mobile.png',fullPage:true});
});

