 test.setTimeout(90000);await page.setViewportSize({width:390,height:844});await signIn(page,'anjali@netaji.school',{stayOnFeed:true});const ad=page.locator('.school-ad-native');await expect(ad).toHaveCount(1);await expect(ad.locator('img')).toBeVisible();await expect.poll(()=>ad.locator('img').evaluate((img:HTMLImageElement)=>img.naturalWidth)).toBeGreaterThan(0);await ad.scrollIntoViewIfNeeded();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);expect((await ad.boundingBox())!.height).toBeLessThan(430);await page.screenshot({path:'docs/screenshots/netaji-native-image-ad-mobile.png'});
 const events:string[]=[];await page.route('**/api/operations/ads/metric',route=>{events.push(route.request().postDataJSON().event);return route.continue();});await ad.getByRole('button',{name:'Next example',exact:true}).click();const video=ad.locator('video');await expect(video).toBeVisible();await expect(video).toHaveAttribute('controls','');await expect(video).not.toHaveAttribute('autoplay');await video.scrollIntoViewIfNeeded();await video.evaluate(async(el:HTMLVideoElement)=>{await el.play();});await expect.poll(()=>video.evaluate((el:HTMLVideoElement)=>el.duration)).toBeGreaterThan(0);await expect.poll(()=>events.includes('video_start')).toBe(true);await video.evaluate((el:HTMLVideoElement)=>{el.currentTime=el.duration-.25;});await expect.poll(()=>events.includes('video_complete')).toBe(true);await page.screenshot({path:'docs/screenshots/netaji-native-video-ad-mobile.png'});
 const audit=await new AxeBuilder({page}).withTags(['wcag2a','wcag2aa','wcag21aa']).analyze();expect(audit.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}))).toEqual([]);await page.setViewportSize({width:1440,height:1000});await ad.scrollIntoViewIfNeeded();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);expect((await ad.boundingBox())!.height).toBeLessThan(450);await page.screenshot({path:'docs/screenshots/netaji-native-video-ad-desktop.png'});
 await page.locator('.teacher-floating-nav button').filter({hasText:'My Classes'}).click();await expect(page.locator('.school-ad')).toHaveCount(1);await page.locator('.teacher-class-card').filter({hasText:'Grade 4 A'}).click();await expect(page.locator('.school-ad')).toHaveCount(0);
